        consentPage: "/consent",
        enforcePerClientResources: true,
        grantTypes: ["authorization_code", "client_credentials"],
        loginPage: "/sign-in",
        resources: [
          {
            accessTokenTtl: 3600,
            allowedScopes: ["openid", "profile", "email", "api:read"],
            identifier: resourceIdentifier,
            name: "Shui API",
